import numpy as np
from scipy.optimize import least_squares
y=dA_dt; vy=np.var(y)
fams={
'Fb':(lambda p:(p[0]+p[1]*t)*A*np.exp(-p[2]*A)+(p[3]+p[4]*t)*A**2+p[5]+p[6]*t, 7),
'Fd':(lambda p:(p[0]*np.exp(-p[1]*t)+p[2])*A**p[3]+p[4]*A**2+p[5]*t*A, 6),
'Fc':(lambda p:(p[0]+p[1]*t+p[2]*t**2)*A*np.log(A+p[3])+(p[4]+p[5]*t)*A**p[6]+p[7], 8),
'Fe':(lambda p:(p[0]+p[1]*t)*A/(1+p[2]*A)+(p[3]+p[4]*t)*A**2/(1+p[5]*A)+p[6], 7),
}
out={}
for name,(f,n) in fams.items():
    best=(9,None)
    for s in range(40):
        rng=np.random.default_rng(s); p0=rng.normal(size=n)*0.7
        try:
            with np.errstate(all='ignore'):
                r=least_squares(lambda p: np.nan_to_num(f(p)-y,nan=1e3,posinf=1e3,neginf=-1e3), p0, max_nfev=2000)
            v=np.mean(r.fun**2)/vy
            if v<best[0]: best=(v,r.x)
